 3	import "time"
 4	
 5	// Budget bounds how long a scan may run and how much it may collect.
 6	type Budget struct {
 7		Deadline time.Time
 8		MaxItems int
 9	}
10	
11	// Scanner walks a tree under a budget.
12	type Scanner struct {
13		budget  Budget
14		visited map[string]bool
15	}
16	
17	func New(b Budget) *Scanner {
18		return &Scanner{budget: b, visited: map[string]bool{}}
19	}
20	
21	func (s *Scanner) Walk(paths []string) ([]string, error) {
22		var out []string
23		for _, p := range paths {
24			if s.visited[p] {
25				continue
26			}
27			s.visited[p] = true
28			if len(out) >= s.budget.MaxItems {
29				break
30			}
31			if time.Now().After(s.budget.Deadline) {
32				for _, q := range paths {
33					if !s.visited[q] {
34						s.visited[q] = false
35					}
36				}
37				break
38			}
39			out = append(out, p)
40		}
41		return out, nil
42	}
